css:
.title-wrap {
  width: 100%;
  padding: 15px;
  box-sizing: border-box;
}

.title {
  color: #bd394f;
  font-weight: normal;
  line-height: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: 0;
  border-top: 1px solid #e3afb7;
  border-bottom: 1px solid #e3afb7;
}

.col {
  display: flex;
  align-items: center;
  border-left: 1px solid #e3afb7;
  padding: 10px clamp(5px, 2vw, 20px);
}

.col:first-child {
  border-left: none;
}

.label {
  font-size: clamp(10px, 1.5vw, 15px);
}

.num {
  font-size: clamp(40px, 6vw, 60px);
  margin-left: clamp(5px, 1.5vw, 15px);
}

.text {
  font-size: clamp(17px, 2.6vw, 26px);
}

.icon {
  margin-left: clamp(5px, 1vw, 10px);
  height: clamp(30px, 5vw, 50px);
}

.icon img {
  margin: 0 !important;
  width: auto;
  height: 100% !important;
  object-fit: contain;
}

.js-fadeUp {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity .8s, transform .8s;
}

.js-fadeUp.is-inview {
  opacity: 1;
  transform: translateY(0);
}

 .toggle-header {
  position: fixed;
  width: 100%;
  top: 0;
  left: 0;
  z-index: 99999;
  background: linear-gradient(to top, rgba(30, 87, 153, 0) 0%, rgba(0, 0, 0, 0.4) 100%);
  transition: transform 0.3s ease-in-out, background 0.3s ease-in-out;
}

 .toggle-header.hide {
  transform: translateY(-100%);
}

 .toggle-header.show {
  transform: translateY(0);
}

 .toggle-header .logoare {
  width: calc(100% - 60px);
  max-width: 1920px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-inline: auto;
  padding: 15px 0;
  line-height: 0;
  column-gap: 20px;
}

 .toggle-header .logoare a {
  position: relative;
  z-index: 99999;
  display: inline-block;
}

 .toggle-header .logoare img {
  width: auto;
  height: 32px !important;
  margin: 0 !important;
}

@media only screen and (max-width: 768px) {
   .toggle-header .logoare {
    width: calc(100% - 40px);
    padding: 10px 0;
    column-gap: 20px;
  }

   .toggle-header.is-open .logoare {
    position: relative;
    background-color: #fff;
    transition: 2s;
    z-index: 99999;
  }
}

 .toggle-header .header_right {
  display: flex;
  align-items: center;
  column-gap: 40px;
  padding-left: 40px;
}

 .toggle-header .header_link {
  position: relative;
  display: block;
  z-index: 99999;
}

 .toggle-header .header_link ul {
  list-style: none;
  margin: 0;
  padding: 0;
  margin-inline: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 1px solid #121212;
  background-color: #121212;
  border-radius: 5px;
}

 .toggle-header .header_link li {
  position: relative;
  width: 100%;
  text-align: center;
  width: 160px;
}

 .toggle-header .header_link li a {
  height: 44px;
  color: #fff;
  font-size: 11px;
  line-height: 1.3;
  display: flex !important;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  background: linear-gradient(145deg, rgb(65, 65, 65) 0%, rgb(18, 18, 18) 100%);
}

@media only screen and (max-width: 1024px) {
   .toggle-header .header_link {
    display: none;
  }
}

 .toggle-header .globalnavi {
  color: #fff;
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  z-index: 200;
}

 .toggle-header .globalnavi a {
  text-decoration: none;
}

 .toggle-header .globalnaviPoint {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 200;
}

 .toggle-header .globalnaviInner {
  max-width: 1350px;
  margin: 0 auto;
  padding: 0;
}

 .toggle-header .globalnavi .mainNav {
  display: block;
  width: min(50%, 320px);
  padding: 0 15px;
  font-size: 14px;
  background-color: transparent;
  list-style: none;
}

 .toggle-header .globalnavi .mainNav li {
  padding: 0;
  border-bottom: #000 solid 1px;
}

 .toggle-header .globalnavi .mainNav a {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #000;
  text-decoration: none;
  font-size: 18px;
  font-family: serif;
  padding: 15px 10px;
  transition: all 0.5s ease-out;
}

 .toggle-header .globalnavi .mainNav a:hover {
  background-color: rgba(0, 0, 0, 0.1);
}

 .toggle-header .globalnavi .mainNav a .nav_en {
  color: rgba(42, 42, 42, 0.5);
  font-size: 11px;
  font-family: serif;
}

 .toggle-header .globalnavi .mainNav a.new:after {
  position: absolute;
  top: 1px;
  left: 10px;
  display: block;
  content: "NEW";
  padding: 2px 5px;
  color: #fff;
  font-size: 10px;
  background-color: #a01300;
  line-height: 1;
}

 .toggle-header .globalnavi .mainNav .on {
  background-color: rgba(0, 0, 0, 0.1);
  color: #000;
}

 .toggle-header .globalnavi .mainNav .off {
  pointer-events: none;
  opacity: 0.2;
}

 .toggle-header .spAccordions {
  display: block !important;
  position: fixed;
  top: 0px;
  right: 0;
  overflow-y: auto;
  height: 100vh;
  width: 38%;
  padding-bottom: 40px;
  -webkit-overflow-scrolling: touch;
  background-color: #fff;
  transform: translateX(100%);
  transition: transform 0.4s;
  z-index: 100;
}

 .toggle-header.is-open .spAccordions {
  transform: translateX(0);
}

 .toggle-header .spAccordions_wrap {
  display: flex;
  justify-content: space-between;
  margin-top: 100px;
  padding: 100px 30px 60px;
}

 .toggle-header .spAccordions_title {
  width: 90px;
  writing-mode: vertical-rl;
  font-size: 86px;
  line-height: 1;
  font-family: serif;
  color: rgba(42, 42, 42, 0.2);
}

@media only screen and (max-width: 1920px) {
   .toggle-header .spAccordions {
    width: min(80%, 680px);
  }
}

@media screen and (max-width: 768px) {
   .toggle-header .spAccordions {
    padding-bottom: 140px;
    width: 100%;
  }

   .toggle-header .spAccordions_wrap {
    margin-top: 60px;
    padding: 40px 30px 60px;
  }

   .toggle-header .spAccordions_title {
    display: none;
  }

   .toggle-header .globalnavi .mainNav {
    width: 100%;
    font-size: 14px;
  }
}

 .toggle-header .menu {
  position: relative;
  width: 80px;
  height: 70px;
  cursor: pointer;
  z-index: 99999;
}

 .toggle-header .menu::before {
  display: none;
}

 .toggle-header .menu .bdr {
  position: relative;
  height: 16px;
  margin: 7px auto 9px;
}

 .toggle-header .menu .menublock {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  transform: translateY(-50%);
  color: #fff;
}

 .toggle-header .menu .bdr span,
 .toggle-header .menu .bdr::before,
 .toggle-header .menu .bdr::after {
  position: absolute;
  left: 0;
  display: block;
  content: "";
  width: 100%;
  height: 0.1rem;
  background-color: #fff;
}

 .toggle-header .menu .bdr span {
  top: 50%;
  transition: 0.3s;
}

 .toggle-header .menu .bdr::before {
  top: 0;
}

 .toggle-header .menu .bdr::after {
  top: 100%;
}

 .toggle-header.is-open .menu .bdr::before {
  animation: menuAnime01 0.4s forwards;
  background-color: #000;
}

 .toggle-header.is-open .menu .bdr::after {
  animation: menuAnime02 0.4s forwards;
  background-color: #000;
}

 .toggle-header.is-open .menu .bdr span {
  opacity: 0;
}

 .toggle-header.is-close .menu .bdr::before {
  animation: menuAnime01_close 0.4s forwards;
}

 .toggle-header.is-close .menu .bdr::after {
  animation: menuAnime02_close 0.4s forwards;
}

@media only screen and (max-width: 768px) {
   .toggle-header .menu {
    width: 50px;
    height: 50px;
  }
}

@keyframes menuAnime01 {
  50% {
    top: 50%;
    transform: rotate(0deg);
  }

  100% {
    top: 50%;
    transform: rotate(18deg);
  }
}

@keyframes menuAnime01_close {
  0% {
    top: 50%;
    transform: rotate(30deg);
  }

  50% {
    top: 50%;
    transform: rotate(0deg);
  }

  100% {
    top: 0;
    transform: rotate(0deg);
  }
}

@keyframes menuAnime02 {
  50% {
    top: 50%;
    transform: rotate(0deg) translateY(0);
  }

  100% {
    top: 50%;
    transform: rotate(-18deg) translateY(0);
  }
}

@keyframes menuAnime02_close {
  0% {
    top: 50%;
    transform: rotate(-30deg) translateY(0);
  }

  50% {
    top: 50%;
    transform: rotate(0deg) translateY(0);
  }

  100% {
    top: 100%;
    transform: rotate(0deg) translateY(-100%);
  }
}

.title {
  position: relative;
  width: 50%;
  margin: 0 auto;
  font-size: 27px;
  color: #000000;
  padding: 100px 0;
  text-shadow: 3px 3px 3px #ffffff, -3px -3px 3px #ffffff, -3px 3px 3px #ffffff, 3px -3px 3px #ffffff, 3px 0px 3px #ffffff, -3px 0px 3px #ffffff, 0px 3px 3px #ffffff, 0px -3px 3px #ffffff;
}

.title-wrap {
  position: relative;
  width: 100%;
  text-align: center;
  overflow: hidden;
}

.title-inner {
  position: relative;
  max-width: unset !important;
  width: 200%;
  left: -50%;
  margin: 0;
  background-image: repeating-conic-gradient(transparent 0,
      transparent 13deg,
      #000000 14deg,
      #000000 15deg,
      transparent 16deg),
    repeating-conic-gradient(transparent 0,
      transparent 20deg,
      #000000 21deg,
      #000000 22deg,
      transparent 23deg),
    repeating-conic-gradient(transparent 0,
      transparent 5deg,
      #000000 6deg,
      #000000 7deg,
      transparent 8deg),
    repeating-conic-gradient(transparent 0,
      transparent 40deg,
      #000000 41deg,
      #000000 42deg,
      transparent 43deg),
    repeating-conic-gradient(transparent 0,
      transparent 10deg,
      #000000 11deg,
      #000000 12deg,
      transparent 13deg);
}

.title-inner::before {
  content: "";
  position: absolute;
  top: -50%;
  left: 0;
  right: 0;
  margin: 0 auto;
  width: auto;
  height: 200%;
  aspect-ratio: 1/1;
  background-image: radial-gradient(#ffffff 0%,
      #ffffff 15%,
      transparent 40%,
      transparent);

}

.title-wrap {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.title h2 {
  text-align: center;
  font-size: 24px;
  font-weight: 700;
  color: #000000;
  line-height: 1.4;
  margin: 0;
}

picture,
img,
video {
  display: inline-block;
  width: 100%;
  height: auto;
  margin: 0 !important;
  vertical-align: bottom;
}

.image-left {
  width: 40px;
  height: auto;
  flex-shrink: 0;
}

.image-right {
  width: 40px;
  height: auto;
  flex-shrink: 0;
}

@media screen and (max-width: 599px) {
  .title-wrap {
    gap: 5px;
  }

  .title h2 {
    font-size: 20px;
  }

  .image-left {
    width: 30px;
  }

  .image-right {
    width: 30px;
  }
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  list-style: none;
  text-decoration: none;
  letter-spacing: 0.15em;
}

.header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 9;
  height: 100px;
  color: #0033a6;
  font-size: 15px;
  font-family: "Noto Sans JP", "Hiragino Kaku Gothic ProN", "Meiryo", sans-serif;
  font-style: normal;
  font-weight: 400;
  background-color: #0d6efd;
}

.header-container {
  display: flex;
  align-items: center;
  height: 100%;
  padding-inline: 30px;
}

.header-logo {
  width: max-content;
  display: flex;
  gap: 30px;
  margin-right: 20px;
  z-index: 2;
}

.header-logo .text-logo img {
  width: auto;
  height: 50px !important;
}

.header-logo .icon-logo img {
  width: auto;
  height: 48px !important;
}

.header-logo-link {
  display: block;
}

@media (hover: hover) and (pointer: fine) {
  .header-logo-link {
    transition: opacity 0.3s;
  }

  .header-logo-link:hover {
    opacity: 0.8;
  }
}

.header-menu {
  width: calc(100% - 255px);
}

.header-nav--item:not(:last-child) {
  border-right: 1px solid #fff;
  padding: 5px 20px;
}

.header-nav--item:last-child {
  margin-left: 20px;
  background-color: #0033a6;
  padding: 10px 30px;
  border-radius: 30px;
}

.header-nav--item a:hover {
  opacity: 0.6;
}

.header-nav-list {
  display: flex;
  align-items: center;
  justify-content: end;
  list-style: none;
  margin: 0;
  padding: 0;
}

.header-nav--item {
  font-weight: 500;
  list-style: none;
  margin: 0;
  padding: 0;
}

.header-nav--item a {
  color: #fff;
  transition: 0.3s;
}

.is-scroll {
  height: 80px;
  transition: 0.8s;
}

.is-scroll .header-container {
  background-color: rgba(255, 255, 255, 0.6);
}

.is-scroll .header-nav--item:not(:last-child) a {
  color: #0033a6;
}

.is-scroll .header-nav--item:not(:last-child) {
  border-right: 1px solid #0033a6;
}

.is-scroll .header-logo .text-logo img,
.is-scroll .header-logo .icon-logo img {
  filter: brightness(0) saturate(100%) invert(13%) sepia(82%) saturate(3363%) hue-rotate(218deg) brightness(97%) contrast(111%);
}

.header-menu-button {
  display: none;
  position: relative;
  padding: 5px;
  border: 0;
  border-radius: 0;
  background: none;
  margin: 0;
  box-shadow: none;
  appearance: none;
  outline: none;
  touch-action: manipulation;
  cursor: pointer;
}

.header-menu-button-lines {
  position: relative;
  display: block;
  width: 30px;
  height: 16px;
}

.header-menu-button-line {
  position: absolute;
  left: 0;
  display: block;
  width: 100%;
  height: 0;
  padding-top: 1px;
  background-color: #fff;
  transition: 0.3s;
}

.header-menu-button-line--top {
  top: 0;
}

.is-menu-opened .header-menu-button-line--top {
  top: 50%;
  transform: translateY(-50%) rotate(45deg);
}

.header-menu-button-line--center {
  top: 50%;
  margin-top: -1px;
}

.is-menu-opened .header-menu-button-line--center {
  background-color: rgba(0, 0, 0, 0);
}

.header-menu-button-line--bottom {
  bottom: 0;
}

.is-menu-opened .header-menu-button-line--bottom {
  bottom: 50%;
  transform: translateY(50%) rotate(-45deg);
}

@media screen and (max-width: 1300px) {
  .header-container {
    padding-inline: 20px;
  }

  .header-logo {
    gap: 20px;
  }

  .header-nav--item:not(:last-child) {
    padding: 5px 15px;
  }

  .header-nav--item:last-child {
    padding: 10px 20px;
  }
}

@media screen and (max-width: 1100px) {
  .header {
    height: 80px;
  }

  .header-logo .text-logo img {
    height: 46px !important;
  }

  .header-logo .icon-logo img {
    height: 44px !important;
  }

  .header-menu-button {
    display: block;
  }

  .header-container {
    padding-inline: 20px;
    justify-content: space-between;
  }
}

@media screen and (max-width: 1100px) and (min-width: 1101px) {
  .header-menu {
    display: block !important;
  }
}

@media screen and (max-width: 1100px) and (max-width: 1100px) {
  .header-menu {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: none;
    overflow-y: auto;
    background-color: rgba(17, 52, 88, 0.9);
  }
}

@media screen and (max-width: 1100px) {
  .header-menu::-webkit-scrollbar {
    display: none;
  }

  .header-menu-container {
    overflow-y: auto;
    height: 100%;
    box-sizing: border-box;
    padding: 120px 4% 4%;
    background: #e2f1f3;
  }

  .header-nav-list {
    display: block;
    flex-wrap: wrap;
    width: 100%;
    margin: 0 auto;
  }

  .header-nav--item:last-child {
    border-radius: 50px;
    width: 96%;
    margin: 20px auto 0;
    padding: 0 20px;
  }

  .header-nav--item:not(:last-child) {
    border-right: unset;
    padding: 0 15px;
  }

  .is-scroll .header-menu-button-line {
    background-color: #0033a6;
  }

  .is-scroll .header-nav--item:not(:last-child) {
    border-right: unset;
  }

  .is-menu-opened .header-menu {
    bottom: 0;
    visibility: visible;
  }

  .header-nav-link {
    display: block;
    padding: 20px;
    color: #0033a6;
    font-weight: bold;
    font-size: 17px;
  }

  .header-nav--item a {
    color: #0033a6;
  }

  .header-nav--item:last-child a {
    color: #fff;
  }

  .is-menu-opened .header-menu-button-line {
    background-color: #0033a6;
  }

  .is-menu-opened .header-menu-button-line--center {
    background-color: unset;
  }

  .is-menu-opened .header-logo .text-logo img,
  .is-menu-opened .header-logo .icon-logo img {
    filter: brightness(0) saturate(100%) invert(13%) sepia(82%) saturate(3363%) hue-rotate(218deg) brightness(97%) contrast(111%);
  }

  .is-animating .header-menu-container {
    scrollbar-width: none;
  }

  .is-animating .header-menu-container::-webkit-scrollbar {
    display: none;
  }
}

@media screen and (max-width: 768px) {
  .header {
    font-size: 14px;
    letter-spacing: 0.1em;
  }

  .header-logo {
    gap: 10px;
    width: 170px;
  }

  .header-logo .text-logo img {
    height: 38px !important;
  }

  .header-logo .icon-logo img {
    height: 36px !important;
  }

  .header-menu-container {
    padding: 100px 4% 4%;
  }

  .header-nav-link {
    padding: 15px 0;
    font-size: min(3.6vw, 20px);
  }
}

.header {
  margin: 0 auto;
  padding: 17px 0;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 999;
  box-sizing: border-box;
}

.header::before {
  background: rgb(255, 255, 255);
  background: linear-gradient(55deg, rgba(255, 255, 255, 1) 0%, rgba(47, 139, 196, 1) 100%);
  content: "";
  height: 100%;
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 0 auto;
  position: relative;
  width: calc(100% - 100px);
  z-index: 1;
}

.header-left {
  width: 228px;
}

.header-right {
  width: calc(100% - 260px);
}

.header-nav__inner {
  display: flex;
  justify-content: flex-end;
  align-items: flex-end;
}

.header-nav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.header-nav__list li:not(:last-child) {
  margin-right: 25px;
}

.header-nav__list li a {
  text-decoration: none !important;
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  transition-duration: .3s;
}

.header-nav__list li a:hover {
  color: #00243B;
}

.contact-btn {
  margin-left: 35px;
  width: 100%;
  max-width: 255px;
}

.contact-btn a {
  text-decoration: none !important;
  background: rgb(227, 128, 128);
  background: linear-gradient(78deg, rgba(227, 128, 128, 1) 0%, rgba(231, 146, 136, 1) 46%, rgba(248, 211, 167, 1) 100%);
  border: 1px solid #fff;
  border-radius: 50px;
  color: #fff;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 16px;
  font-weight: 500;
  height: 60px;
  transition-duration: .3s;
  width: 100%;
}

.contact-btn a:hover {
  background: rgb(255 255 255 / 18%);
}

@media screen and (max-width: 1268px) {
  .header-nav__list li:not(:last-child) {
    margin-right: 15px;
  }

  .contact-btn {
    margin-left: 25px;
    max-width: 200px;
  }
}

@media screen and (max-width: 1168px) {
  .header-nav__list li a {
    font-size: 13px;
  }

  .contact-btn {
    max-width: 180px;
  }

  .contact-btn a {
    font-size: 14px;
  }
}

@media screen and (max-width: 1068px) {
  .header-inner {
    width: calc(100% - 50px);
  }

  .header-left {
    width: 180px;
  }

  .header-right {
    width: calc(100% - 210px);
  }
}

@media screen and (max-width: 968px) {
  .header {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 75px;
