/* ウィジェットに例でのせている要素の設定ここまで */

.nav-ring {
  position: fixed;
  top: 0;
  left: 0;
  font-size: 16px;
  line-height: 1;
  z-index: 10;
}

.nav-ring * {
  box-sizing: border-box;
  max-width: unset !important;
}

.nav-ring .menu {
  pointer-events: none;
}

.nav-ring .menu input[type=radio] {
  display: none;
}

.nav-ring .menu--circle {
  position: absolute;
  z-index: 13;
  width: 244px;
  height: 244px;
  background-color: transparent;
  overflow: hidden;
}

.nav-ring .menu__toggle {
  z-index: 11;
  position: absolute;
  top: -100px;
  left: -100px;
  width: 200px;
  height: 200px;
  background-color: #efefef;
  border-radius: 50%;
  transition: -webkit-transform 1.3s;
  transition: transform 1.3s;
  transition: transform 1.3s, -webkit-transform 1.3s;
  cursor: pointer;
  pointer-events: auto;
}

.nav-ring .menu__listings {
  z-index: 10;
  position: absolute;
  top: -200px;
  left: -200px;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  -webkit-transform: scale(0.1) rotate(150deg);
  transform: scale(0.1) rotate(150deg);
  transition: -webkit-transform 1s;
  transition: transform 1s;
  transition: transform 1s, -webkit-transform 1s;
}

.nav-ring .menu__arrow {
  visibility: hidden;
  position: absolute;
}

.nav-ring .menu__arrow ul {
  padding: 0;
  margin: 0;
  list-style: none;
}

.nav-ring .menu__arrow--top {
  top: 0.5em;
  left: 220px;
}

.nav-ring .menu__arrow--top .arrow {
  -webkit-transform: rotate(-45deg);
  transform: rotate(-45deg);
}

.nav-ring .menu__arrow--left {
  top: 220px;
  left: 0.5em;
}

.nav-ring .menu__arrow--left .arrow {
  -webkit-transform: rotate(-135deg);
  transform: rotate(-135deg);
}

.nav-ring .menu .icon {
  position: absolute;
  top: 70%;
  left: 70%;
  -webkit-transform: translateX(-50%) translateY(-50%);
  transform: translateX(-50%) translateY(-50%);
}

.nav-ring .menu .hamburger {
  content: " ";
  position: relative;
  width: 20px;
  border: 2px solid #333333;
  border-radius: 5px;
  transition: all 0.3s ease;
}

.nav-ring .menu .hamburger:after,
.nav-ring .menu .hamburger:before {
  content: " ";
  position: absolute;
  left: 50%;
  width: 100%;
  border: 2px solid #333333;
  border-radius: 5px;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  transition-property: top, bottom, -webkit-transform;
  transition-property: top, bottom, transform;
  transition-property: top, bottom, transform, -webkit-transform;
  transition-duration: 1s, 1s, 0.25s;
}

.nav-ring .menu .hamburger:after {
  top: -8px;
}

.nav-ring .menu .hamburger:before {
  bottom: -8px;
}

.nav-ring .arrow {
  width: 20px;
  height: 20px;
  border-right: 6.7px solid #333333;
  border-top: 6.7px solid #333333;
  border-radius: 3px;
  transition: border-color 0.3s;
  cursor: pointer;
  pointer-events: auto;
}

.nav-ring .arrow:hover {
  border-color: #ff947f;
  transition: border-color 0.3s;
}

.nav-ring .circle {
  position: relative;
  padding: 0;
  margin: 0;
  height: 100%;
  width: 100%;
  background-color: #efefef;
  border-radius: 50%;
  -webkit-transform: rotate(144deg);
  transform: rotate(144deg);
  overflow: hidden;
  list-style: none;
}

.nav-ring .circle li {
  position: absolute;
  top: 0;
  right: 0;
  width: 50%;
  height: 50%;
  -webkit-transform-origin: 0 100%;
  transform-origin: 0 100%;
}

.nav-ring .circle li .placeholder {
  position: absolute;
  left: -100%;
  padding-top: 1.5em;
  width: 200%;
  height: 200%;
  text-align: center;
  -webkit-transform: skewY(54deg) rotate(18deg);
  transform: skewY(54deg) rotate(18deg);
}

.nav-ring .circle li .placeholder .upside {
  -webkit-transform: rotate(180deg);
  transform: rotate(180deg);
}

.nav-ring .circle li .placeholder a {
  text-decoration: none;
  pointer-events: auto;
}

.nav-ring .circle li .placeholder button {
  pointer-events: auto;
}

.nav-ring .circle li .placeholder .button {
  font-size: 2.3em;
  background-color: transparent;
  border: none;
  color: #333333;
  cursor: pointer;
}

.nav-ring .circle li .placeholder .button:hover {
  color: #c1264e;
}

.nav-ring .circle li .placeholder .button svg {
  width: 1em;
  fill: #333333;
}

.nav-ring .circle li .placeholder .button svg:hover {
  fill: #c1264e;
}

.nav-ring .circle li .placeholder .button img {
  width: 1em;
}

.nav-ring .circle li .placeholder .button img:hover {
  opacity: 0.7;
}

.nav-ring .circle li:nth-child(1) {
  -webkit-transform: rotate(0deg) skewY(-54deg);
  transform: rotate(0deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(2) {
  -webkit-transform: rotate(-36deg) skewY(-54deg);
  transform: rotate(-36deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(3) {
  -webkit-transform: rotate(-72deg) skewY(-54deg);
  transform: rotate(-72deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(4) {
  -webkit-transform: rotate(-108deg) skewY(-54deg);
  transform: rotate(-108deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(5) {
  -webkit-transform: rotate(-144deg) skewY(-54deg);
  transform: rotate(-144deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(6) {
  -webkit-transform: rotate(-180deg) skewY(-54deg);
  transform: rotate(-180deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(7) {
  -webkit-transform: rotate(-216deg) skewY(-54deg);
  transform: rotate(-216deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(8) {
  -webkit-transform: rotate(-252deg) skewY(-54deg);
  transform: rotate(-252deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(9) {
  -webkit-transform: rotate(-288deg) skewY(-54deg);
  transform: rotate(-288deg) skewY(-54deg);
}

.nav-ring .circle li:nth-child(10) {
  -webkit-transform: rotate(-324deg) skewY(-54deg);
  transform: rotate(-324deg) skewY(-54deg);
}

.nav-ring #nav-ring-menu {
  display: none;
}

.nav-ring #nav-ring-menu:checked~label .menu__listings {
  -webkit-transform: rotate(10deg) scale(1);
  transform: rotate(10deg) scale(1);
  transition: -webkit-transform 1s;
  transition: transform 1s;
  transition: transform 1s, -webkit-transform 1s;
}

.nav-ring #nav-ring-menu:checked~label .menu__toggle {
  background-color: #ffffff;
  transition: all 1s;
}

.nav-ring #nav-ring-menu:checked~label .hamburger {
  border-color: transparent;
  transition: border-color 0.3s;
}

.nav-ring #nav-ring-menu:checked~label .hamburger:after {
  top: -2px;
  border-color: #333333;
  -webkit-transform: translateX(-50%) rotate(45deg);
  transform: translateX(-50%) rotate(45deg);
  transition-property: top, -webkit-transform;
  transition-property: top, transform;
  transition-property: top, transform, -webkit-transform;
  transition-duration: 0.25s, 1s;
}

.nav-ring #nav-ring-menu:checked~label .hamburger:before {
  bottom: -2px;
  border-color: #333333;
  -webkit-transform: translateX(-50%) rotate(-45deg);
  transform: translateX(-50%) rotate(-45deg);
  transition-property: bottom, -webkit-transform;
  transition-property: bottom, transform;
  transition-property: bottom, transform, -webkit-transform;
  transition-duration: 0.25s, 1s;
}

.nav-ring #nav-ring-menu:checked~label .menu__arrow {
  visibility: visible;
  transition: all 1s 1.1s;
}

.nav-ring #nav-ring-menu:checked~label .menu__arrow--top label {
  display: none;
}

.nav-ring #nav-ring-menu:checked~label .menu__arrow--top label[for=nav-ring-up-0] {
  display: block;
}

.nav-ring #nav-ring-menu:checked~label #nav-ring-up-0:checked~.menu__listings {
  -webkit-transform: rotate(116deg);
  transform: rotate(116deg);
}

.nav-ring #nav-ring-menu:checked~label #nav-ring-up-0:checked~.menu__arrow--top label {
  display: none;
}

.nav-ring #nav-ring-menu:checked~label #nav-ring-up-0:checked~.menu__arrow--top label[for=nav-ring-up-1] {
  display: block;
}

.nav-ring #nav-ring-menu:checked~label #nav-ring-up-1:checked~.menu__listings {
  -webkit-transform: rotate(224deg);
  transform: rotate(224deg);
}

.nav-ring #nav-ring-menu:checked~label #nav-ring-up-1:checked~.menu__listings~.menu__arrow--top label {
  display: none;
}

.nav-ring #nav-ring-menu:checked~label #nav-ring-up-1:checked~.menu__listings~.menu__arrow--top label[for=nav-ring-up-2] {
  display: block;
}

