/* 全体の設定 */
.ribonHead {
  /*外側の余白｜上余白｜左右余白｜下余白｜*/
  margin: 2em 50px 1em;
  /* 横幅（全体 - 左右余白） */
  width: calc(100% - 100px);
  /* 文字間 */
  letter-spacing: .04em;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  center = センタリングする
  flex-end = 右側から配置する*/
  justify-content: center;
}



/* リボン内のテキストが入る所 */
.ribonHead span {
  /*横幅*/
  width: 100%;
  /*文字色*/
  color: #fff;
  /*背景色*/
  background: #fa4141;
  /*文字サイズ*/
  font-size: 19px;
  /* 文字の位置 */
  text-align: center;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  center = センタリングする
  flex-end = 右側から配置する*/
  justify-content: center;
  /*垂直方向にの配置位置を設定。
  center = 中央配置
  flex-start = 先頭にまとめる
  flex-end = 末尾にまとめる*/
  align-items: center;
}

.ribonHead:before,
.ribonHead:after {
  display: block;
  height: 0px;
  content: '';
  /*上部の背景色に合わせる（3行以上になる場合は、1行=20pxずつ追加してください）*/
  border: 49px solid #fa4141;
}

.ribonHead:before {
  /* left: -40px; */
  border-left-width: 15px;
  border-left-color: transparent;
}

.ribonHead:after {
  /* right: -40px; */
  border-right-width: 15px;
  border-right-color: transparent;
}


/* スマホ表示の時 */
@media screen and (max-width: 767px) {
  .ribonHead {
    /*外側の余白｜上余白｜左右余白｜下余白｜*/
    margin: 2em 0 1em;
    /* 横幅 */
    width: 100%;
  }

  /* リボンのテキストサイズの調整 */
  .ribonHead span {
    font-size: 4.0vw;
  }
}

