  /*水平方向の字間のスペース*/
  letter-spacing: 0.05em
}

h2 {
  /*文字色*/
  color: #505050;
  /*背景色*/
  background: #dbebf8;
  padding: 20px 20px 20px 45px;
  display: inline-block;
  line-height: 1.3;
  vertical-align: middle;
  border-radius: 40px 0 0 40px;
  margin: 5px 0;
  position: relative;
}

h2:first-child {
  margin-left: 0;
}

h2:first-child:before {
  /* カラーコードで○の色指定*/
  color: #fff;
  content: "●";
  margin-left: -2.1rem;
  position: absolute;
  display: block;
  top: 50%;
  -webkit-transform: translateY(-50%);
  -moz-transform: translateY(-50%);
  -ms-transform: translateY(-50%);
  transform: translateY(-50%);
}

.blueline {
  /*文字色*/
  color: #364e96;
  /* 上線。線の種類｜線の太さ｜線の色*/
  border-top: solid 3px #364e96;
  /* 下線。線の種類｜線の太さ｜線の色*/
  border-bottom: solid 3px #364e96;
  /*文字から線までの余白。上下｜左右*/
  padding: 10px 0;
  /*線の外側余白。上下｜左右*/
  margin: 5px 0;
}

h2 {
  /*文字サイズ*/
  font-size: 20px;
}

.headerline {
  padding: 1em;
  background: #fffaf4;
  border-left: solid 10px #ffaf58;
  font-size: 16px;
}

@media screen and (max-width:600px) {
  .headerline {
    font-size: 12px;
  }
}

.headerline p {
  font-size: 1.6875em;
  color: #222222;
  font-weight: bold;
  line-height: 1.75;
  margin: 0;
}
